; ---- goalCol = viewCell()
        call    viewCell
        mov     ax, [viewCell__ret]
        mov     [moview__goalCol], ax
        ret

; ============================================== sub viewGotoLine ====

viewGotoLine:
; ---- lines = textLines()
        call    textLines
        mov     ax, [textLines__ret]
        mov     [viewGotoLine__lines], ax
; ---- if ( lines > 0 && ln >= lines ) ln = lines - 1
        test    ax, ax
        jbe     .L330                       ; unsigned >
        mov     ax, [viewGotoLine__ln]
        mov     bx, [viewGotoLine__lines]
        cmp     ax, bx
        jb      .L330                       ; unsigned >=
        mov     ax, [viewGotoLine__lines]
        dec     ax
        mov     [viewGotoLine__ln], ax
.L330:
; ---- viewPlace( ln, lineColAt( ln, goalCol, viewTabStop ) )
        mov     ax, [viewGotoLine__ln]
        push    ax                          ; argument evaluated before any is stored
        mov     ax, [viewGotoLine__ln]
        mov     [lineColAt__ln], ax
        mov     ax, [moview__goalCol]
        mov     [lineColAt__cell], ax
        mov     word [lineColAt__stop], 8
        call    lineColAt
        mov     ax, [lineColAt__ret]
        mov     [moview__viewPlace__col], ax
        pop     ax
        mov     [moview__viewPlace__ln], ax
        call    moview__viewPlace
        ret

; ============================================== sub moview__viewPlace ====

moview__viewPlace:
; ---- lines = textLines()
        call    textLines
        mov     ax, [textLines__ret]
        mov     [moview__viewPlace__lines], ax
; ---- curLine = ln
        mov     ax, [moview__viewPlace__ln]
        mov     [moview__curLine], ax
; ---- if ( lines > 0 && curLine >= lines ) curLine = lines - 1
        mov     ax, [moview__viewPlace__lines]
        test    ax, ax
        jbe     .L334                       ; unsigned >
        mov     ax, [moview__curLine]
        mov     bx, [moview__viewPlace__lines]
        cmp     ax, bx
        jb      .L334                       ; unsigned >=
        mov     ax, [moview__viewPlace__lines]
        dec     ax
        mov     [moview__curLine], ax
.L334:
; ---- curCol = col
        mov     ax, [moview__viewPlace__col]
        mov     [moview__curCol], ax
; ---- if ( curCol > lineLength( curLine ) ) curCol = lineLength( curLine )
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [moview__curLine]
        mov     [lineLength__ln], ax
        call    lineLength
        mov     ax, [lineLength__ret]
        mov     bx, ax
        pop     ax
        cmp     ax, bx
        jbe     .L338                       ; unsigned >
        mov     ax, [moview__curLine]
        mov     [lineLength__ln], ax
        call    lineLength
        mov     ax, [lineLength__ret]
        mov     [moview__curCol], ax
.L338:
; ---- viewFollow()
        call    moview__viewFollow
        ret

; ============================================== sub viewRenderRow ====

viewRenderRow:
; ---- ln = top + y
        mov     ax, [moview__top]
        mov     bx, [viewRenderRow__y]
        add     ax, bx
        mov     [viewRenderRow__ln], ax
; ---- n = 0
        mov     word [viewRenderRow__n], 0
; ---- if ( ln < textLines() ) n = lineCells( ln, left, width, viewTabStop, addr( row ) )
        mov     ax, [viewRenderRow__ln]
        push    ax                          ; save lhs: rhs is not a leaf
        call    textLines
        mov     ax, [textLines__ret]
        mov     bx, ax
        pop     ax
        cmp     ax, bx
        jae     .L341                       ; unsigned <
        mov     ax, [viewRenderRow__ln]
        mov     [lineCells__ln], ax
        mov     ax, [moview__left]
        mov     [lineCells__from], ax
        mov     ax, [moview__width]
        mov     [lineCells__cells], ax
        mov     word [lineCells__stop], 8
        mov     ax, moview__row             ; link-time constant
        mov     [lineCells__at], ax
        call    lineCells
        mov     ax, [lineCells__ret]
        mov     [viewRenderRow__n], ax
.L341:
; ---- viewRow( y, addr( row ), n )
        mov     ax, [viewRenderRow__y]
        mov     [viewRow__y], ax
        mov     ax, moview__row             ; link-time constant
        mov     [viewRow__at], ax
        mov     ax, [viewRenderRow__n]
        mov     [viewRow__n], ax
        call    viewRow
        ret

; ============================================== sub viewRender ====

viewRender:
; ---- for ( u16 y = 0; y < height; y++ ) {
        mov     word [viewRender__y], 0
.L344:
        mov     ax, [viewRender__y]
        mov     bx, [moview__height]
        cmp     ax, bx
        jae     .L346                       ; unsigned <
; ---- viewRenderRow( y )
        mov     ax, [viewRender__y]
        mov     [viewRenderRow__y], ax
        call    viewRenderRow
.L345:
        inc     word [viewRender__y]
        jmp     .L344
.L346:
        ret

; ============================================== sub viewRow ====

viewRow:
; ---- for ( u16 i = 0; i < n; i++ ) {
        mov     word [viewRow__i], 0
.L348:
        mov     ax, [viewRow__i]
        mov     bx, [viewRow__n]
        cmp     ax, bx
        jae     .L350                       ; unsigned <
; ---- putChar( peek8( at + i ) )
        mov     ax, [viewRow__at]
        mov     bx, [viewRow__i]
        add     ax, bx
        mov     bx, ax
        mov     al, [bx]                    ; peek8 - unchecked, by design
        mov     [putChar__c], al            ; u8 -> u8, no widening
        call    putChar
.L349:
        inc     word [viewRow__i]
        jmp     .L348
.L350:
; ---- putChar( '|' )
        mov     byte [putChar__c], 124
        call    putChar
; ---- newline()
        call    newline
        ret

; ============================================== sub showWhere ====

showWhere:
; ---- putNumber( viewTop() )
        call    viewTop
        mov     ax, [viewTop__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
; ---- putNumber( viewLeft() )
        call    viewLeft
        mov     ax, [viewLeft__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- newline()
        call    newline
        ret

; ============================================== sub showAt ====

showAt:
; ---- putNumber( viewLine() )
        call    viewLine
        mov     ax, [viewLine__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
; ---- putNumber( viewCol() )
        call    viewCol
        mov     ax, [viewCol__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- newline()
        call    newline
        ret

; ============================================== sub typeIn ====

typeIn:
; ---- while ( peek8( at ) != 0 ) {
.L352:
        mov     ax, [typeIn__at]
        mov     bx, ax
        mov     al, [bx]                    ; peek8 - unchecked, by design
        test    al, al
        je      .L354                       ; unsigned !=
; ---- textLoad( peek8( at ) )
        mov     ax, [typeIn__at]
        mov     bx, ax
        mov     al, [bx]                    ; peek8 - unchecked, by design
        mov     [textLoad__ch], al          ; u8 -> u8, no widening
        call    textLoad
; ---- at++
        inc     word [typeIn__at]
.L353:
        jmp     .L352
.L354:
        ret

; ============================================== sub showDoc ====

showDoc:
; ---- putNumber( textDoc() )
        call    textDoc
        mov     ax, [textDoc__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
; ---- putNumber( viewDoc() )
        call    viewDoc
        mov     ax, [viewDoc__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
; ---- putNumber( textLines() )
        call    textLines
        mov     ax, [textLines__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- newline()
        call    newline
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        pop     es
        ret

